"""Evaluate research requests against supplied evidence and policy."""

from __future__ import annotations

import copy
import json
from pathlib import Path
from typing import Any


def _canonical(value: Any) -> str:
    """Return a stable JSON representation for exact value comparisons."""
    return json.dumps(
        value, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    )


def evaluate(
    request: dict[str, Any],
    evidence: list[dict[str, Any]],
    policy: dict[str, Any],
) -> dict[str, Any]:
    """Evaluate request using only the supplied evidence and policy."""
    required = policy.get("required_conditions", [])
    request_conditions = request.get("conditions", {})
    missing = sorted(name for name in required if name not in request_conditions)
    if missing:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": missing,
        }

    eligible: list[dict[str, Any]] = []
    for record in evidence:
        if record.get("claim") != request.get("claim"):
            continue
        if record.get("withdrawn", False):
            continue
        if policy.get("require_verified", False) and record.get("verified") is not True:
            continue

        record_conditions = record.get("conditions", {})
        if not isinstance(record_conditions, dict):
            continue
        if any(
            name not in record_conditions
            or _canonical(record_conditions[name])
            != _canonical(request_conditions[name])
            for name in required
        ):
            continue
        eligible.append(record)

    superseded: set[str] = set()
    for record in eligible:
        replaced = record.get("supersedes", [])
        if isinstance(replaced, str):
            superseded.add(replaced)
        elif isinstance(replaced, list):
            superseded.update(item for item in replaced if isinstance(item, str))

    eligible = [
        record for record in eligible if record.get("source") not in superseded
    ]
    if not eligible:
        return {
            "status": "unknown",
            "value": None,
            "sources": [],
            "unknowns": ["no matching evidence"],
        }

    sources = sorted(record["source"] for record in eligible)
    values: dict[str, Any] = {}
    for record in eligible:
        value = record.get("value")
        values.setdefault(_canonical(value), value)

    if len(values) != 1:
        return {
            "status": "conflict",
            "value": None,
            "sources": sources,
            "unknowns": ["source disagreement"],
        }

    value = next(iter(values.values()))
    return {
        "status": "unsupported" if value is False else "supported",
        "value": copy.deepcopy(value),
        "sources": sources,
        "unknowns": [],
    }


def _write_report() -> None:
    base = Path(__file__).resolve().parent
    with (base / "requests.json").open(encoding="utf-8") as stream:
        requests = json.load(stream)
    with (base / "evidence.json").open(encoding="utf-8") as stream:
        evidence = json.load(stream)
    with (base / "policy.json").open(encoding="utf-8") as stream:
        policy = json.load(stream)
    report = [evaluate(request, evidence, policy) for request in requests]
    with (base / "report.json").open("w", encoding="utf-8") as stream:
        json.dump(report, stream, indent=2, ensure_ascii=False)
        stream.write("\n")


if __name__ == "__main__":
    _write_report()
